widget.solution:
#include <vector>

std::vector<double> simple_returns(const std::vector<double>& prices) {
    std::vector<double> out;
    for (std::size_t i = 1; i < prices.size(); ++i) {
        out.push_back((prices[i] - prices[i - 1]) / prices[i - 1]);
    }
    return out;
}

